import * as U from '../ui.js';
let courseId=new URLSearchParams(location.search).get('course')||'',unmarked=false;
const update=U.mount(()=>{let sessions=U.db.class_sessions.filter(s=>(!courseId||s.course_id===courseId)&&s.status!=='cancelled'&&(s.status==='completed'||U.day(s.starts_at)===U.TODAY)).sort((a,b)=>new Date(b.starts_at)-new Date(a.starts_at));if(unmarked)sessions=sessions.filter(s=>!U.db.attendance.some(a=>a.class_session_id===s.id));return U.heading('Every class counts','Keep track. Stay on track.','See where you stand and mark each class with confidence.',U.button('Mark attendance','attendance'))+`<div class="grid2" style="margin-bottom:24px">${U.db.courses.filter(c=>!courseId||c.id===courseId).map(c=>{let a=U.attendanceStats(c.id),warn=a.percent!==null&&a.percent<c.minimum_attendance_percent;return `<article class="card subject-colored" style="${U.subjectStyle(c.id)}"><div class="section-head"><div><h2>${U.esc(c.course_code)}</h2><p>${U.esc(c.name)}</p></div>${U.tag(a.percent===null?'Not marked yet':warn?'Needs attention':'On track',warn?'warn':'blue')}</div><div class="metric">${a.percent===null?'—':a.percent+'%'} <span> / ${c.minimum_attendance_percent}% required</span></div><div class="progress"><i style="width:${a.percent||0}%;${warn?'background:#d1aa64':''}"></i></div><p class="small muted">${a.present} attended / ${a.total} counted · ${a.unmarked} unmarked</p></article>`}).join('')}</div><div class="toolbar"><div class="tabs"><button data-att-filter="all" class="${!unmarked?'active':''}">All records</button><button data-att-filter="unmarked" class="${unmarked?'active':''}">Unmarked</button></div><select id="att-course" aria-label="Course"><option value="">All courses</option>${U.db.courses.map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${U.esc(c.course_code)}</option>`).join('')}</select></div>${U.section('Class history',`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Course</th><th>Time</th><th>Attendance</th><th></th></tr></thead><tbody>${sessions.map(s=>{let a=U.db.attendance.find(a=>a.class_session_id===s.id);return `<tr><td>${U.date(U.day(s.starts_at))}</td><td>${U.esc(U.course(s.course_id)?.course_code)}</td><td>${U.time(s.starts_at)}</td><td>${U.tag(a?.status||'Unmarked',a?.status==='absent'?'warn':a?'blue':'')}</td><td><button class="btn" data-attend="${s.id}">${a?'Correct record':'Mark attendance'}</button></td></tr>`}).join('')||'<tr><td colspan="5">No matching class records.</td></tr>'}</tbody></table></div>`)}<div class="note" style="margin-top:20px">${U.icon('info')}<span>No attendance history was provided in the screenshot. Initial thresholds are editable defaults; set each course’s real policy before relying on alerts. Percentages use completed, marked classes. Cancelled classes are excluded. Late and excused records follow the policies set in each course.</span></div>`});
document.addEventListener('click',e=>{let b=e.target.closest('[data-att-filter]');if(b){unmarked=b.dataset.attFilter==='unmarked';update()}});document.addEventListener('change',e=>{if(e.target.id==='att-course'){courseId=e.target.value;update()}});
